from math import comb

def mcnemar(b, c):
    n = b + c
    tail = sum(comb(n, i) for i in range(min(b, c) + 1)) / 2 ** n
    return round(min(1.0, 2 * tail), 4)

print(mcnemar(2, 0), mcnemar(6, 0))

